def ref(source,location): return dict(source_id=source,location=location)
def obs(value,source,location,note=''): return dict(value=value,evidence=[ref(source,location)],note=note)
def count(class_,value,source,page,basis='inscribed objects',date=None,certainty='documented',note='',unit='objects'):
    return dict(object_class=class_,value=value,unit=unit,count_basis=basis,count_date=date,inscription_assessment=certainty,note=note,evidence=[ref(source,page)])

ROWS=[]
def row(name,aliases,main,loc,campaign,publications,counts,meta,hold,problems,coverage='',post=None,final=None):
    r=dict(canonical_name=name,alternative_spellings=aliases,primary_read=ref(main,loc),excavation_campaigns=campaign,primary_publications=publications,reported_counts=counts,metadata_observation=meta,holdings=hold,open_problems=problems,local_coverage_judgment=coverage,post_cisi_finds=post or dict(status='unresolved',note='No dated later inscribed find verified in the searched sources; this is not a finding of absence.'),final_report=final or dict(status='unresolved',note='No completed campaign monograph verified by the recorded searches.'))
    ROWS.append(r); return r
def campaign(years,director,institution,s,p,note=''): return dict(years=years,director=director,institution=institution,evidence=[ref(s,p)],note=note)
def pub(s,p,kind='preliminary'): return dict(source_id=s,location=p,publication_kind=kind)
def meta(s,p,flags,note):
    keys=['findspot','stratum_or_phase','absolute_dates','dimensions','material','photographs','drawings','registration_numbers']
    return {k:dict(availability=v,evidence=[ref(s,p)],scope=note) for k,v in zip(keys,flags.split())}
def holdings(s,p,note,status='partial'): return dict(status=status,observation=note,evidence=[ref(s,p)])
def final(s,read=False): return dict(status='bibliographically_verified',source_id=s,relevant_object_pages_read=read)
def post(s,p,note,kind='after_site_catalogue'): return dict(status='documented',comparison_kind=kind,observation=note,evidence=[ref(s,p)])

